import base64, hashlib, io, json, pathlib, subprocess, sys, tempfile, zipfile
root = pathlib.Path('products/distribution/sqlite-gumroad-fit/private-exercise')
expected_hash = '80b451146e7cdf45c3adada847d22dbe1dcaa8c192077cdf08b6d1fe323c6364'
output = root / 'delivery' / 'archive-behavior-readback.json'
result = {'expected_archive_sha256': expected_hash, 'scope': 'Fictional fixtures only', 'runs': {}, 'passed': False}
try:
    for candidate in sorted(root.rglob('*.b64')):
        try:
            archive = base64.b64decode(b''.join(candidate.read_bytes().split()), validate=True)
        except ValueError:
            continue
        if hashlib.sha256(archive).hexdigest() == expected_hash:
            break
    else:
        raise ValueError('Exact archive not found among committed base64 files')
    result['archive_path'] = str(candidate)
    result['archive_sha256'] = expected_hash
    with zipfile.ZipFile(io.BytesIO(archive)) as bundle, tempfile.TemporaryDirectory() as directory:
        assert sorted(bundle.namelist()) == ['invoice-fixtures.json', 'invoice-regression.py']
        bundle.extractall(directory)
        for mode, expected_exit, expected_failure in [('join', 1, 'multiple_tags'), ('distinct_amount', 1, 'equal_invoice_amounts'), ('exists', 0, None)]:
            run = subprocess.run([sys.executable, 'invoice-regression.py', mode], cwd=directory, capture_output=True, text=True, timeout=15)
            result['runs'][mode] = {'exit': run.returncode, 'expected_exit': expected_exit, 'expected_failing_case': expected_failure, 'stdout': run.stdout, 'stderr': run.stderr}
    result['passed'] = all(run['exit'] == run['expected_exit'] for run in result['runs'].values())
except Exception as error:
    result['error'] = str(error)
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
